CREATE TABLE "cenit"."purchase_request_lines" (
	"id" uuid PRIMARY KEY NOT NULL,
	"request_id" uuid NOT NULL,
	"position" integer NOT NULL,
	"description" text,
	"provider" text,
	"cost_center" text,
	"line_unit" text,
	"quantity" text,
	"price" numeric(255, 0),
	"amount" numeric(255, 0),
	"charge_account" text,
	"university_code" text,
	"campus_code" text,
	"unit_code" text,
	"project_code" text,
	"accounting_code" text,
	CONSTRAINT "purchase_line_position" UNIQUE("request_id","position"),
	CONSTRAINT "purchase_line_range" CHECK ("cenit"."purchase_request_lines"."position" BETWEEN 1 AND 100),
	CONSTRAINT "purchase_line_amounts" CHECK (("cenit"."purchase_request_lines"."price" IS NULL OR "cenit"."purchase_request_lines"."price" >= 0) AND ("cenit"."purchase_request_lines"."amount" IS NULL OR "cenit"."purchase_request_lines"."amount" >= 0)),
	CONSTRAINT "purchase_line_description" CHECK ("cenit"."purchase_request_lines"."description" IS NULL OR (length("cenit"."purchase_request_lines"."description") BETWEEN 1 AND 1000 AND "cenit"."purchase_request_lines"."description" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_line_text_0" CHECK ("cenit"."purchase_request_lines"."provider" IS NULL OR (length("cenit"."purchase_request_lines"."provider") BETWEEN 1 AND 255 AND "cenit"."purchase_request_lines"."provider" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_line_text_1" CHECK ("cenit"."purchase_request_lines"."cost_center" IS NULL OR (length("cenit"."purchase_request_lines"."cost_center") BETWEEN 1 AND 255 AND "cenit"."purchase_request_lines"."cost_center" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_line_text_2" CHECK ("cenit"."purchase_request_lines"."line_unit" IS NULL OR (length("cenit"."purchase_request_lines"."line_unit") BETWEEN 1 AND 255 AND "cenit"."purchase_request_lines"."line_unit" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_line_text_3" CHECK ("cenit"."purchase_request_lines"."quantity" IS NULL OR (length("cenit"."purchase_request_lines"."quantity") BETWEEN 1 AND 255 AND "cenit"."purchase_request_lines"."quantity" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_line_text_4" CHECK ("cenit"."purchase_request_lines"."charge_account" IS NULL OR (length("cenit"."purchase_request_lines"."charge_account") BETWEEN 1 AND 255 AND "cenit"."purchase_request_lines"."charge_account" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_line_text_5" CHECK ("cenit"."purchase_request_lines"."university_code" IS NULL OR (length("cenit"."purchase_request_lines"."university_code") BETWEEN 1 AND 255 AND "cenit"."purchase_request_lines"."university_code" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_line_text_6" CHECK ("cenit"."purchase_request_lines"."campus_code" IS NULL OR (length("cenit"."purchase_request_lines"."campus_code") BETWEEN 1 AND 255 AND "cenit"."purchase_request_lines"."campus_code" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_line_text_7" CHECK ("cenit"."purchase_request_lines"."unit_code" IS NULL OR (length("cenit"."purchase_request_lines"."unit_code") BETWEEN 1 AND 255 AND "cenit"."purchase_request_lines"."unit_code" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_line_text_8" CHECK ("cenit"."purchase_request_lines"."project_code" IS NULL OR (length("cenit"."purchase_request_lines"."project_code") BETWEEN 1 AND 255 AND "cenit"."purchase_request_lines"."project_code" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_line_text_9" CHECK ("cenit"."purchase_request_lines"."accounting_code" IS NULL OR (length("cenit"."purchase_request_lines"."accounting_code") BETWEEN 1 AND 255 AND "cenit"."purchase_request_lines"."accounting_code" ~ '[^[:space:]]'))
);
--> statement-breakpoint
CREATE TABLE "cenit"."purchase_requests" (
	"id" uuid PRIMARY KEY NOT NULL,
	"operation_id" uuid NOT NULL,
	"payload_hash" text NOT NULL,
	"request_number" text NOT NULL,
	"oracle_id" text,
	"sender" text,
	"recipient" text,
	"sent_date" date NOT NULL,
	"sent_time" text,
	"description" text NOT NULL,
	"total_amount" numeric(255, 0) NOT NULL,
	"tax_amount" numeric(255, 0),
	"attachment_reference" text,
	"document" text,
	"document_type" text,
	"bi" text,
	"rut" text,
	"unit_name" text,
	"item" text,
	"payment_situation" text,
	"source" text DEFAULT 'manual' NOT NULL,
	"review_status" text DEFAULT 'pending' NOT NULL,
	"version" integer DEFAULT 1 NOT NULL,
	"created_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"reviewed_by" uuid,
	"reviewed_at" timestamp with time zone,
	CONSTRAINT "purchase_operation" UNIQUE("created_by","operation_id"),
	CONSTRAINT "purchase_source" CHECK ("cenit"."purchase_requests"."source" = 'manual'),
	CONSTRAINT "purchase_version" CHECK ("cenit"."purchase_requests"."version" > 0),
	CONSTRAINT "purchase_hash" CHECK ("cenit"."purchase_requests"."payload_hash" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "purchase_review" CHECK (("cenit"."purchase_requests"."review_status" = 'pending' AND "cenit"."purchase_requests"."reviewed_by" IS NULL AND "cenit"."purchase_requests"."reviewed_at" IS NULL) OR ("cenit"."purchase_requests"."review_status" = 'reviewed' AND "cenit"."purchase_requests"."reviewed_by" IS NOT NULL AND "cenit"."purchase_requests"."reviewed_at" IS NOT NULL AND "cenit"."purchase_requests"."reviewed_at" >= "cenit"."purchase_requests"."created_at")),
	CONSTRAINT "purchase_amounts" CHECK ("cenit"."purchase_requests"."total_amount" >= 0 AND ("cenit"."purchase_requests"."tax_amount" IS NULL OR "cenit"."purchase_requests"."tax_amount" >= 0)),
	CONSTRAINT "purchase_date" CHECK ("cenit"."purchase_requests"."sent_date" BETWEEN DATE '0001-01-01' AND DATE '9999-12-31'),
	CONSTRAINT "purchase_time" CHECK ("cenit"."purchase_requests"."sent_time" IS NULL OR "cenit"."purchase_requests"."sent_time" ~ '^([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9]$'),
	CONSTRAINT "purchase_text_0" CHECK ("cenit"."purchase_requests"."request_number" IS NULL OR (length("cenit"."purchase_requests"."request_number") BETWEEN 1 AND 255 AND "cenit"."purchase_requests"."request_number" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_text_1" CHECK ("cenit"."purchase_requests"."oracle_id" IS NULL OR (length("cenit"."purchase_requests"."oracle_id") BETWEEN 1 AND 255 AND "cenit"."purchase_requests"."oracle_id" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_text_2" CHECK ("cenit"."purchase_requests"."sender" IS NULL OR (length("cenit"."purchase_requests"."sender") BETWEEN 1 AND 255 AND "cenit"."purchase_requests"."sender" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_text_3" CHECK ("cenit"."purchase_requests"."recipient" IS NULL OR (length("cenit"."purchase_requests"."recipient") BETWEEN 1 AND 255 AND "cenit"."purchase_requests"."recipient" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_text_4" CHECK ("cenit"."purchase_requests"."attachment_reference" IS NULL OR (length("cenit"."purchase_requests"."attachment_reference") BETWEEN 1 AND 255 AND "cenit"."purchase_requests"."attachment_reference" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_text_5" CHECK ("cenit"."purchase_requests"."document" IS NULL OR (length("cenit"."purchase_requests"."document") BETWEEN 1 AND 255 AND "cenit"."purchase_requests"."document" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_text_6" CHECK ("cenit"."purchase_requests"."document_type" IS NULL OR (length("cenit"."purchase_requests"."document_type") BETWEEN 1 AND 255 AND "cenit"."purchase_requests"."document_type" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_text_7" CHECK ("cenit"."purchase_requests"."bi" IS NULL OR (length("cenit"."purchase_requests"."bi") BETWEEN 1 AND 255 AND "cenit"."purchase_requests"."bi" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_text_8" CHECK ("cenit"."purchase_requests"."rut" IS NULL OR (length("cenit"."purchase_requests"."rut") BETWEEN 1 AND 255 AND "cenit"."purchase_requests"."rut" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_text_9" CHECK ("cenit"."purchase_requests"."unit_name" IS NULL OR (length("cenit"."purchase_requests"."unit_name") BETWEEN 1 AND 255 AND "cenit"."purchase_requests"."unit_name" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_text_10" CHECK ("cenit"."purchase_requests"."item" IS NULL OR (length("cenit"."purchase_requests"."item") BETWEEN 1 AND 255 AND "cenit"."purchase_requests"."item" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_text_11" CHECK ("cenit"."purchase_requests"."payment_situation" IS NULL OR (length("cenit"."purchase_requests"."payment_situation") BETWEEN 1 AND 255 AND "cenit"."purchase_requests"."payment_situation" ~ '[^[:space:]]')),
	CONSTRAINT "purchase_description" CHECK (length("cenit"."purchase_requests"."description") BETWEEN 1 AND 1000 AND "cenit"."purchase_requests"."description" ~ '[^[:space:]]')
);
